import os
import json
import pandas as pd

# Load farm_registry.csv
with open("/app/dataset/farm_registry.csv", "r") as f:
    lines = f.readlines()
registry = []
for line in lines[1:]:
    parts = line.strip().split(',')
    if len(parts) == 2:
        registry.append((parts[0].strip(), parts[1].strip()))

def read_lines_robust(csv_path):
    for encoding in ['utf-8', 'utf-16', 'utf-16-le', 'utf-16-be', 'latin-1']:
        try:
            with open(csv_path, 'r', encoding=encoding) as file:
                lines = [file.readline() for _ in range(10)]
            return lines, encoding
        except Exception:
            continue
    raise ValueError(f"Could not read {csv_path}")

for name, f_id in registry:
    csv_path = f"/app/dataset/production_{f_id}.csv"
    if os.path.exists(csv_path):
        lines, encoding = read_lines_robust(csv_path)
        has_metadata = any("System Export Report" in l for l in lines[:3])
        skiprows = 3 if has_metadata else 0

        # Determine delimiter
        delim = ';' if ';' in lines[3] else ','

        df = pd.read_csv(csv_path, skiprows=skiprows, encoding=encoding, sep=delim)
        df.columns = [c.strip() for c in df.columns]

        # Robustly parse timestamps
        def parse_ts(ts_str):
            if not isinstance(ts_str, str):
                return pd.NaT
            ts_str = ts_str.strip()
            for fmt in ('%Y-%m-%d %H:%M:%S', '%d.%m.%Y %H:%M:%S', '%Y-%m-%dT%H:%M:%S'):
                try:
                    return pd.to_datetime(ts_str, format=fmt)
                except ValueError:
                    continue
            return pd.NaT

        df['dt'] = df['timestamp'].apply(parse_ts)
        df = df.dropna(subset=['dt']).sort_values('dt')

        diffs = df['dt'].diff().dropna().unique()
        print(f"{f_id}: unique diffs = {diffs}, rows = {len(df)}")

