import os
import pandas as pd

# FARM_B: Pacific Sunfield (America/Los_Angeles, UTC-8)
# FARM_C: Sakura Energy Site (Asia/Tokyo, UTC+9)

for f_id in ['FARM_B', 'FARM_C']:
    csv_path = f"/app/dataset/production_{f_id}.csv"
    delim = ';' if f_id == 'FARM_C' else ','
    encoding = 'utf-8'
    df = pd.read_csv(csv_path, skiprows=3, encoding=encoding, sep=delim)
    df.columns = [c.strip() for c in df.columns]

    # Drop duplicates on timestamp
    ts_col = df.columns[0]
    df = df.drop_duplicates(subset=[ts_col], keep='last')

    # Parse timestamps
    def parse_ts(ts_str):
        if not isinstance(ts_str, str):
            return pd.NaT
        ts_str = ts_str.strip()
        for fmt in ('%Y-%m-%d %H:%M:%S', '%d.%m.%Y %H:%M:%S'):
            try:
                return pd.to_datetime(ts_str, format=fmt)
            except ValueError:
                continue
        return pd.NaT

    df['dt'] = df[ts_col].apply(parse_ts)
    df = df.dropna(subset=['dt'])
    df['hour'] = df['dt'].dt.hour

    val_col = 'value' if f_id == 'FARM_B' else 'reading'

    def parse_float(val):
        if not isinstance(val, str):
            try:
                return float(val)
            except:
                return float('nan')
        val = val.strip()
        if val.lower() == 'offline':
            return float('nan')
        val = val.replace('.', '').replace(',', '.')
        try:
            return float(val)
        except ValueError:
            return float('nan')

    df['val_clean'] = df[val_col].apply(parse_float)

    # Apply calibration offset
    # FARM_B offset is -0.04
    # FARM_C offset is 18000.0
    offset = -0.04 if f_id == 'FARM_B' else 18000.0
    df['val_true'] = df['val_clean'] - offset

    # Drop negative values
    df = df[df['val_true'] >= 0]

    hourly_avg = df.groupby('hour')['val_true'].mean()
    print(f"\n--- {f_id} hourly true production average ---")
    print(hourly_avg)

