import os
import json
import pandas as pd

# Load farm_registry.csv
with open("/app/dataset/farm_registry.csv", "r") as f:
    lines = f.readlines()
registry = []
for line in lines[1:]:
    parts = line.strip().split(',')
    if len(parts) == 2:
        registry.append((parts[0].strip(), parts[1].strip()))

# Load sensors_calibration.json
with open("/app/dataset/sensors_calibration.json", "r") as f:
    calib_data = json.load(f)
farms_calib = calib_data["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]

# Load farms.csv
farms_df = pd.read_csv("/app/dataset/farms.csv")

def parse_float(val):
    if not isinstance(val, str):
        try:
            return float(val)
        except:
            return float('nan')
    val = val.strip()
    if val.lower() == 'offline':
        return float('nan')
    val = val.replace('.', '').replace(',', '.')
    try:
        return float(val)
    except ValueError:
        return float('nan')

def parse_ts(ts_str):
    if not isinstance(ts_str, str):
        return pd.NaT
    ts_str = ts_str.strip()
    for fmt in ('%Y-%m-%d %H:%M:%S', '%d.%m.%Y %H:%M:%S'):
        try:
            return pd.to_datetime(ts_str, format=fmt)
        except ValueError:
            continue
    return pd.NaT

def get_matching_column(df_cols, target_col_name):
    if target_col_name in df_cols:
        return target_col_name
    stripped_target = target_col_name.strip()
    for col in df_cols:
        if col.strip() == stripped_target:
            return col
    for col in df_cols:
        if col.strip().lower() == stripped_target.lower():
            return col
    return None

def read_lines_robust(csv_path):
    for encoding in ['utf-8', 'utf-16', 'utf-16-le', 'utf-16-be', 'latin-1']:
        try:
            with open(csv_path, 'r', encoding=encoding) as file:
                lines = [file.readline() for _ in range(10)]
            return lines, encoding
        except Exception:
            continue
    raise ValueError(f"Could not read {csv_path}")

results = []
for name, f_id in registry:
    calib = farms_calib.get(f_id, {})
    val_col_json = calib.get("calibration_data", {}).get("value_column_name")
    offset = calib.get("calibration_data", {}).get("calibration_offset")
    read_type = calib.get("sensor_info", {}).get("reading_type")
    unit = calib.get("sensor_info", {}).get("unit")

    # Get timezone
    match_row = farms_df[farms_df['farm_name'].str.strip().str.lower() == name.strip().lower()]
    timezone = match_row.iloc[0]['timezone'].strip()

    csv_path = f"/app/dataset/production_{f_id}.csv"
    if os.path.exists(csv_path):
        # Read file lines robustly to find delimiter and encoding
        lines, encoding = read_lines_robust(csv_path)
        has_metadata = any("System Export Report" in l for l in lines[:3])
        skiprows = 3 if has_metadata else 0
        delim = ';' if ';' in lines[3] else ','

        df = pd.read_csv(csv_path, skiprows=skiprows, encoding=encoding, sep=delim)

        ts_col = get_matching_column(df.columns, 'timestamp')
        val_col = get_matching_column(df.columns, val_col_json)

        # Deduplicate on timestamp
        df = df.drop_duplicates(subset=[ts_col], keep='last')

        df['dt_local'] = df[ts_col].apply(parse_ts)
        df = df.dropna(subset=['dt_local']).sort_values('dt_local')

        # Apply maintenance exclusions in local civil time
        if f_id == 'FARM_C':
            # Sakura Energy Site
            df = df[~((df['dt_local'] >= pd.Timestamp('2024-03-16 08:00:00')) & (df['dt_local'] <= pd.Timestamp('2024-03-16 12:00:00')))]
        elif f_id == 'FARM_F':
            # Vistula Photovoltaics
            df = df[~((df['dt_local'] >= pd.Timestamp('2024-03-15 12:00:00')) & (df['dt_local'] <= pd.Timestamp('2024-03-15 14:00:00')))]

        # Parse value column
        df['val_clean'] = df[val_col].apply(parse_float)
        df['val_true'] = df['val_clean'] - offset
        # Drop negative values
        df = df[df['val_true'] >= 0]

        # Localize to UTC
        df['dt_utc'] = df['dt_local'].dt.tz_localize(timezone, ambiguous='NaT', nonexistent='NaT').dt.tz_convert('UTC')
        df = df.dropna(subset=['dt_utc'])

        # Filter UTC reporting day
        df_day = df[(df['dt_utc'] >= pd.Timestamp('2024-03-15 00:00:00', tz='UTC')) &
                    (df['dt_utc'] < pd.Timestamp('2024-03-16 00:00:00', tz='UTC'))].copy()

        # Compute energy
        if len(df_day) == 0:
            results.append((f_id, read_type, unit, 0, 0))
            continue

        if read_type == 'energy':
            # Energy unit conversion
            unit_lower = unit.lower()
            if 'mwh' in unit_lower:
                conv = 1000.0
            elif 'wh' in unit_lower:
                conv = 0.001
            elif 'btu' in unit_lower:
                conv = 0.000293071
            else:
                conv = 1.0 # kwh

            total_kwh_nom = df_day['val_true'].sum() * conv
            total_kwh_act = total_kwh_nom
        else:
            # Power unit conversion
            unit_lower = unit.lower()
            if 'mw' in unit_lower:
                conv = 1000.0
            elif 'w' in unit_lower:
                conv = 0.001
            else:
                conv = 1.0 # kw

            # Method A: Nominal interval
            diffs = df['dt_local'].diff().dropna()
            mode_diff = diffs.mode()[0]
            nom_hours = mode_diff.total_seconds() / 3600.0

            total_kwh_nom = (df_day['val_true'] * conv).sum() * nom_hours

            # Method B: Actual diffs
            df['dt_diff'] = df['dt_local'].diff()
            df.loc[df['dt_diff'].isna(), 'dt_diff'] = mode_diff
            df['dt_diff_hours'] = df['dt_diff'].dt.total_seconds() / 3600.0

            df_day2 = df[(df['dt_utc'] >= pd.Timestamp('2024-03-15 00:00:00', tz='UTC')) &
                         (df['dt_utc'] < pd.Timestamp('2024-03-16 00:00:00', tz='UTC'))]
            total_kwh_act = (df_day2['val_true'] * conv * df_day2['dt_diff_hours']).sum()

        results.append((f_id, read_type, unit, total_kwh_nom, total_kwh_act))

print("\nMethod Comparison (Total kWh):")
print(f"{'Farm ID':<10} | {'Type':<8} | {'Unit':<6} | {'Nominal':<12} | {'Actual':<12}")
print("-" * 60)
for f_id, rtype, unit, nom, act in results:
    print(f"{f_id:<10} | {rtype:<8} | {unit:<6} | {nom:<12.4f} | {act:<12.4f}")

