        offset = calib.get("calibration_data", {}).get("calibration_offset")
        read_type = calib.get("sensor_info", {}).get("reading_type")
        unit = calib.get("sensor_info", {}).get("unit")

        # Get timezone
        match_row = farms_df[farms_df['farm_name'].str.strip().str.lower() == name.strip().lower()]
        timezone = match_row.iloc[0]['timezone'].strip()

        csv_path = f"/app/dataset/production_{f_id}.csv"
        if not os.path.exists(csv_path):
            results[f_id] = 0
            continue

        try:
            lines, encoding = read_lines_robust(csv_path)
            has_metadata = any("System Export Report" in l for l in lines[:3])
            skiprows = 3 if has_metadata else 0
            delim = ';' if ';' in lines[3] else ','

            df = pd.read_csv(csv_path, skiprows=skiprows, encoding=encoding, sep=delim)

            ts_col = get_matching_column(df.columns, 'timestamp')
            val_col = get_matching_column(df.columns, val_col_json)
            temp_col = get_matching_column(df.columns, 'inverter_temperature_C')

            # Deduplicate on timestamp
            df = df.drop_duplicates(subset=[ts_col], keep='last')

            df['dt_local'] = df[ts_col].apply(parse_ts)
            df = df.dropna(subset=['dt_local']).sort_values('dt_local')

            # 1. Apply Safety Rules (Inverter temperature spikes)
            if temp_col in df.columns:
                def parse_temp(val):
                    if not isinstance(val, str):
                        try:
                            return float(val)
                        except:
                            return float('nan')
                    val = val.strip().replace(',', '.')
                    try:
                        return float(val)
                    except ValueError:
                        return float('nan')
                df['temp_clean'] = df[temp_col].apply(parse_temp)

                # Identify rows with temperature > 85.0
                spike_times = df[df['temp_clean'] > 85.0]['dt_local'].tolist()

                # Invalidate rows in the 45 minutes immediately following any spike
                # A row is invalidated if spike_time < dt_local <= spike_time + 45 min
                if len(spike_times) > 0:
                    for spike in spike_times:
                        end_invalid = spike + timedelta(minutes=45)
                        df = df[~((df['dt_local'] > spike) & (df['dt_local'] <= end_invalid))]

            # 2. Apply Maintenance Exclusions (in local civil time)
            if f_id == 'FARM_C':
                # Sakura Energy Site: firmware update (8:00 to 12:00 on March 16th local time)
                # Exclude [08:00:00, 12:00:00]
                df = df[~((df['dt_local'] >= pd.Timestamp('2024-03-16 08:00:00')) & 
                          (df['dt_local'] <= pd.Timestamp('2024-03-16 12:00:00')))]
            elif f_id == 'FARM_F':
                # Vistula Photovoltaics: Scheduled cleaning (12:00 to 14:00 on March 15th local time)
                # Exclude [12:00:00, 14:00:00]
                df = df[~((df['dt_local'] >= pd.Timestamp('2024-03-15 12:00:00')) & 
                          (df['dt_local'] <= pd.Timestamp('2024-03-15 14:00:00')))]

            # 3. Parse value column and apply calibration offset
            df['val_clean'] = df[val_col].apply(lambda x: parse_float_robust(x, delim))
            df['val_true'] = df['val_clean'] - offset

            # Drop negative values (only valid after the calibration offset is applied)
            df = df[df['val_true'] >= 0]

            # 4. Localize to UTC and filter by reporting day
            df['dt_utc'] = df['dt_local'].dt.tz_localize(timezone, ambiguous='NaT', nonexistent='NaT').dt.tz_convert('UTC')
            df = df.dropna(subset=['dt_utc'])

            df_day = df[(df['dt_utc'] >= pd.Timestamp('2024-03-15 00:00:00', tz='UTC')) &
                        (df['dt_utc'] < pd.Timestamp('2024-03-16 00:00:00', tz='UTC'))]

            if len(df_day) == 0:
                results[f_id] = 0
                continue

            # 5. Integrate to kWh
            if read_type == 'energy':
                # Energy unit conversion
                unit_lower = unit.lower()
                if 'mwh' in unit_lower:
                    conv = 1000.0
                elif 'kwh' in unit_lower:
                    conv = 1.0
                elif 'wh' in unit_lower:
                    conv = 0.001
                elif 'btu' in unit_lower:
                    # British Thermal Unit: 1 BTU = 0.000293071 kWh
                    conv = 0.000293071
                else:
                    conv = 1.0 # default kwh

                total_kwh = df_day['val_true'].sum() * conv
            else:
                # Power unit conversion
                unit_lower = unit.lower()
                if 'mw' in unit_lower:
                    conv = 1000.0
                elif 'kw' in unit_lower:
                    conv = 1.0
                elif 'w' in unit_lower:
                    conv = 0.001
                else:
                    conv = 1.0 # default kw

                # Find nominal interval (mode of diffs on df)
                diffs = df['dt_local'].diff().dropna()
                if len(diffs) > 0:
                    mode_diff = diffs.mode()[0]
                    nom_hours = mode_diff.total_seconds() / 3600.0
                else:
                    nom_hours = 5 / 60.0 # fallback

                total_kwh = (df_day['val_true'] * conv).sum() * nom_hours

            results[f_id] = int(round(total_kwh))
        except Exception as e:
            print(f"Error processing {f_id}: {e}")
            results[f_id] = 0

    return results

